function validate([s, words]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50000) return 's needs 1 to 50000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 5000) return 'words needs 1 to 5000 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 50) return 'Each word has 1 to 50 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Words may contain only lowercase letters.';
  }
  return null;
}

