function numMatchingSubseq(s, words) {
  const positions = Array.from({ length: 26 }, () => []);
  for (let i = 0; i < s.length; i++) {
    positions[s.charCodeAt(i) - 97].push(i);
  }

  let count = 0;
  for (const word of words) {
    let prev = -1;
    let matched = true;
    for (const ch of word) {
      const list = positions[ch.charCodeAt(0) - 97];
      let left = 0;
      let right = list.length;
      while (left < right) {
        const mid = (left + right) >> 1;
        if (list[mid] > prev) {
          right = mid;
        } else {
          left = mid + 1;
        }
      }
      if (left === list.length) {
        matched = false;
        break;
      }
      prev = list[left];
    }
    if (matched) {
      count++;
    }
  }
  return count;
}

