function numMatchingSubseq(s, words) {
  let total = 0;
  for (const w of words) {
    let j = 0;
    for (let i = 0; i < s.length && j < w.length; i++) if (s[i] === w[j]) j++;
    if (j === w.length) total++;
  }
  return total;
}

