function generate(rand, size) {
  const large = size === 'large';
  const k = large ? 3 + Math.floor(rand() * 24) : 1 + Math.floor(rand() * 4);
  const letter = (alpha) => String.fromCharCode(97 + Math.floor(rand() * alpha));
  const n = large ? 10000 : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let i = 0; i < n; i++) s += letter(k);
  const count = large ? 400 : 1 + Math.floor(rand() * 7);
  const maxLen = large ? 40 : 5;
  const words = [];
  for (let w = 0; w < count; w++) {
    const len = 1 + Math.floor(rand() * maxLen);
    let word = '';
    if (rand() < 0.5) {
      // Build a real subsequence by picking increasing positions of s.
      const picks = [];
      for (let t = 0; t < Math.min(len, n); t++) picks.push(Math.floor(rand() * n));
      picks.sort((a, b) => a - b);
      const used = [...new Set(picks)];
      for (const p of used) word += s[p];
    } else {
      const alpha = Math.min(26, k + 2);
      for (let t = 0; t < len; t++) word += letter(alpha);
    }
    if (word.length === 0) word = letter(k);
    if (!large && words.length > 0 && rand() < 0.2) word = words[Math.floor(rand() * words.length)];
    words.push(word);
  }
  return [s, words];
}
